from security import validate_access_code
assert validate_access_code('123456') == '123456'
for value in (' 123456 ', 123456, '１２３４５６', '12345', None, '12345a'):
    try:
        validate_access_code(value)
    except ValueError:
        pass
    else:
        raise AssertionError(repr(value))

