import assert from 'node:assert/strict';
import { badge } from './ui/badge.mjs';
import { renderToolbar } from './toolbar.mjs';
assert.equal(badge('Ready', {compact: true}), '<span class="badge badge--compact">Ready</span>');
assert.equal(badge('<&', {compact: true}), '<span class="badge badge--compact">&lt;&amp;</span>');
assert.equal(badge('Ready', {}), '<span class="badge">Ready</span>');
assert.equal(badge('Ready', {compact: false}), '<span class="badge">Ready</span>');
assert.equal(renderToolbar(), '<span class="badge badge--compact">Ready</span>');
